-- Allow safe inline cover images generated by the Ochilink Admin image uploader.
BEGIN;

ALTER TABLE public.apps
    DROP CONSTRAINT IF EXISTS apps_cover_image_url_https;

ALTER TABLE public.apps
    DROP CONSTRAINT IF EXISTS apps_cover_image_source_safe;

ALTER TABLE public.apps
    ADD CONSTRAINT apps_cover_image_source_safe
    CHECK (
        cover_image_url IS NULL
        OR cover_image_url ~ '^https://[^[:space:]]+$'
        OR (
            length(cover_image_url) <= 150000
            AND cover_image_url ~ '^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$'
        )
    );

INSERT INTO public.hub_schema_migrations (version)
VALUES ('012_inline_app_cover_images')
ON CONFLICT (version) DO NOTHING;

COMMIT;
